<template><AppLayout><div class="mx-auto max-w-3xl space-y-5"><RouterLink to="/supplier/accounts" class="text-sm text-primary-600">← {{ t('marketplace.accounts') }}</RouterLink><div v-if="loading" class="card p-6">{{ t('marketplace.loading') }}</div><div v-else-if="error && !account" class="card p-6" role="alert">{{ t('marketplace.loadFailed') }} <button class="text-primary-600 underline" @click="load">{{ t('marketplace.retry') }}</button></div><template v-else-if="account"><div class="card space-y-4 p-6"><h1 class="text-xl font-semibold">{{ account.name }}</h1><div class="grid gap-3 text-sm sm:grid-cols-2"><p>{{ t('marketplace.provider') }}: {{ account.platform }} / {{ account.type }}</p><div>{{ t('marketplace.reviewStatus') }}: <SupplierStatusBadge kind="review" :status="account.offer.review_status" /></div><div>{{ t('marketplace.healthStatus') }}: <SupplierStatusBadge kind="credential" :status="account.credential_status" /></div><p>{{ t('marketplace.currentRequests') }}: {{ account.current_concurrency }}</p></div><p v-if="readOnly" class="text-sm text-amber-600">{{ t('marketplace.readOnly') }}</p></div><section class="card space-y-3 p-6"><h2 class="font-semibold">{{ t('marketplace.usageSummary') }}</h2><div v-if="account.usage" class="grid gap-2 text-sm sm:grid-cols-2"><p>{{ t('marketplace.requests') }}: {{ account.usage.requests }}</p><p>{{ t('marketplace.inputTokens') }}: {{ account.usage.input_tokens }}</p><p>{{ t('marketplace.outputTokens') }}: {{ account.usage.output_tokens }}</p><p>{{ t('marketplace.consumerCharge') }}: {{ account.usage.consumer_charge }}</p><p>{{ t('marketplace.supplierNet') }}: {{ account.usage.supplier_net }}</p></div><p v-else class="text-sm text-gray-500">{{ t('marketplace.noUsage') }}</p></section><section class="card space-y-3 p-6"><h2 class="font-semibold">{{ t('marketplace.reviewHistory') }}</h2><ul v-if="account.reviews?.length" class="space-y-2 text-sm"><li v-for="(review, index) in account.reviews" :key="index"><SupplierStatusBadge kind="review" :status="review.status" /> {{ review.created_at }}<span v-if="review.reason"> — {{ review.reason }}</span></li></ul><p v-else class="text-sm text-gray-500">{{ t('marketplace.noReviews') }}</p></section><form class="card space-y-4 p-6" @submit.prevent="save"><h2 class="font-semibold">{{ t('marketplace.configuration') }}</h2><label class="block text-sm">{{ t('marketplace.accountName') }}<input v-model="name" required class="input mt-1 w-full" :disabled="readOnly || busy || saveUnknown" /></label><fieldset :disabled="readOnly || !provider || busy || saveUnknown"><legend class="text-sm">{{ t('marketplace.allowedModels') }}</legend><label v-for="model in provider?.models || account.offer.allowed_models" :key="model" class="mr-4 inline-flex items-center gap-1 text-sm"><input v-model="models" type="checkbox" :value="model" />{{ model }}</label></fieldset><AccountConcurrencyForm v-model="concurrency" :max="options?.max_supplier_concurrency || account.concurrency" :disabled="readOnly || !options || busy || saveUnknown" /><p v-if="!options" class="text-sm text-amber-600">{{ t('marketplace.optionsUnavailable') }}</p><div v-if="conflict" role="alert" class="space-y-2 text-sm text-amber-600"><p>{{ t('marketplace.versionConflict') }} <button type="button" class="underline" @click="refreshVersion">{{ t('marketplace.refreshVersion') }}</button></p><template v-if="conflictLatest"><p>{{ t('marketplace.latestConfiguration') }}: {{ conflictLatest.name }} · {{ conflictLatest.concurrency }} · {{ conflictLatest.offer.allowed_models.join(', ') }}</p><p>{{ t('marketplace.yourConfiguration') }}: {{ name }} · {{ concurrency }} · {{ models.join(', ') }}</p><button type="button" data-test="ack-detail-conflict" class="underline" @click="acknowledgeConflict">{{ t('marketplace.reviewedConfiguration') }}</button></template></div><p v-if="saveUnknown" role="alert" class="text-sm text-amber-600">{{ t('marketplace.operationUnknown') }} <button type="button" data-test="check-save" class="underline" :disabled="busy" @click="checkSave">{{ t('marketplace.checkStatus') }}</button> <button type="button" data-test="retry-save" class="underline" :disabled="busy" @click="retrySave">{{ t('marketplace.retrySameSave') }}</button></p><p v-if="error" role="alert" class="text-sm text-red-600">{{ t('marketplace.submitFailed') }}</p><button class="btn-primary" :disabled="readOnly || !options || !provider || busy || saveUnknown || conflict || !valid">{{ t('marketplace.save') }}</button></form><div class="card space-y-3 p-6"><h2 class="font-semibold">{{ t('marketplace.actions') }}</h2><p class="text-sm text-gray-500">{{ t('marketplace.probeExplanation') }}</p><div class="flex flex-wrap gap-2"><button v-if="['draft', 'rejected'].includes(account.offer.review_status) && !readOnly" class="btn-secondary" :disabled="busy || saveUnknown" @click="confirmAction('submit')">{{ t('marketplace.submitReview') }}</button><button v-if="account.offer.enabled" class="btn-secondary" :disabled="busy || saveUnknown" @click="confirmAction('pause')">{{ t('marketplace.pause') }}</button><button v-else-if="account.offer.review_status === 'approved' && !readOnly" class="btn-secondary" :disabled="busy || saveUnknown" @click="confirmAction('resume')">{{ t('marketplace.resume') }}</button><button v-if="!readOnly && ['api_key', 'oauth'].includes(account.type)" data-test="replace-credentials" class="btn-secondary" :disabled="busy || saveUnknown" @click="openCredentials">{{ t('marketplace.replaceCredentials') }}</button><button class="btn-secondary" :disabled="busy || saveUnknown" @click="performProbe">{{ t('marketplace.probe') }}</button><button v-if="account.offer.review_status !== 'revoked'" class="btn-secondary text-red-600" :disabled="busy || saveUnknown" @click="confirmAction('revoke')">{{ t('marketplace.revoke') }}</button></div><p v-if="probeResult" role="status" class="text-sm">{{ probeResult }}</p></div></template><AccountCredentialDialog v-if="credentialDialog && account" :account="account" @close="credentialDialog = false" @saved="credentialDialog = false; load()" /><ConfirmDialog :show="!!action" :title="t(`marketplace.${action || 'pause'}`)" :message="t(`marketplace.${action || 'pause'}Explanation`)" :danger="action === 'revoke'" @cancel="action = null" @confirm="perform" /></div></AppLayout></template>
<script setup lang="ts">
import { computed, onMounted, onUnmounted, nextTick, ref, watch } from 'vue'
import { onBeforeRouteLeave, onBeforeRouteUpdate, useRoute } from 'vue-router'
import { useI18n } from 'vue-i18n'
import AppLayout from '@/components/layout/AppLayout.vue'
import ConfirmDialog from '@/components/common/ConfirmDialog.vue'
import SupplierStatusBadge from '@/components/supplier/SupplierStatusBadge.vue'
import AccountCredentialDialog from '@/components/supplier/AccountCredentialDialog.vue'
import AccountConcurrencyForm from '@/components/supplier/AccountConcurrencyForm.vue'
import { getAccount, getSupplierOptions, updateAccount, accountAction } from '@/api/supplier'
import { useWorkModeStore } from '@/stores/workMode'
import type { SupplierAccount, SupplierOptions } from '@/types/marketplace'
const { t } = useI18n(); const route = useRoute(); const store = useWorkModeStore(); const account = ref<SupplierAccount | null>(null); const options = ref<SupplierOptions | null>(null); const name = ref(''); const models = ref<string[]>([]); const concurrency = ref(1); const loading = ref(true); const error = ref(false); const conflict = ref(false); const busy = ref(false); const probeResult = ref(''); const action = ref<'submit' | 'pause' | 'resume' | 'revoke' | null>(null)
const conflictLatest = ref<SupplierAccount | null>(null); const credentialDialog = ref(false); const saveUnknown = ref(false); const submitted = ref<{ expected_version: number; name: string; concurrency: number; allowed_models: string[] } | null>(null)
onBeforeRouteLeave(() => !(busy.value || saveUnknown.value))
onBeforeRouteUpdate(() => !(busy.value || saveUnknown.value))
function beforeUnload(event: BeforeUnloadEvent) { if (busy.value || saveUnknown.value) { event.preventDefault(); event.returnValue = '' } }
window.addEventListener('beforeunload', beforeUnload)
const readOnly = computed(() => store.capabilities?.supplier_status === 'suspended'); const provider = computed(() => options.value?.providers?.find(p => p.platform === account.value?.platform)); const valid = computed(() => !!name.value.trim() && models.value.length > 0 && Number.isInteger(concurrency.value) && concurrency.value > 0 && concurrency.value <= (options.value?.max_supplier_concurrency || 0))
watch([name, models, concurrency], () => { if (!loading.value) store.dirty = true }, { deep: true })
async function load() { loading.value = true; error.value = false; try { const [a, o] = await Promise.all([getAccount(Number(route.params.id)), getSupplierOptions().catch(() => null)]); account.value = a; options.value = o; name.value = a.name; models.value = [...a.offer.allowed_models]; concurrency.value = a.concurrency; await nextTick(); store.dirty = false } catch { error.value = true } finally { loading.value = false } }
async function refreshVersion() { try { conflictLatest.value = await getAccount(Number(route.params.id)) } catch { error.value = true } }
function acknowledgeConflict() { if (!conflictLatest.value) return; account.value = conflictLatest.value; conflictLatest.value = null; conflict.value = false }
async function save() { if (!account.value || !valid.value || busy.value || saveUnknown.value || readOnly.value || conflict.value) return; busy.value = true; error.value = false; submitted.value = { expected_version: account.value.offer.version, name: name.value.trim(), concurrency: concurrency.value, allowed_models: [...models.value] }; try { account.value = await updateAccount(account.value.id, submitted.value); store.dirty = false } catch (e) { const status = (e as { status?: number }).status; if (status === 409) conflict.value = true; else if ([400, 401, 403, 404, 410, 422].includes(status || 0)) error.value = true; else saveUnknown.value = true } finally { busy.value = false } }
async function checkSave() { if (!account.value || !submitted.value || busy.value) return; busy.value = true; try { const latest = await getAccount(account.value.id); const snapshot = submitted.value; if (latest.offer.version > snapshot.expected_version) { saveUnknown.value = false; if (latest.name === snapshot.name && latest.concurrency === snapshot.concurrency && [...latest.offer.allowed_models].sort().join('\0') === [...snapshot.allowed_models].sort().join('\0')) { account.value = latest; store.dirty = false } else { conflictLatest.value = latest; conflict.value = true; store.dirty = true } } } catch { /* Keep the unknown state until confirmed. */ } finally { busy.value = false } }
async function retrySave() { if (!account.value || !submitted.value || busy.value || !saveUnknown.value) return; busy.value = true; let inspect = false; try { account.value = await updateAccount(account.value.id, submitted.value); saveUnknown.value = false; store.dirty = false } catch (e) { if ((e as { status?: number }).status === 409) inspect = true } finally { busy.value = false } if (inspect) await checkSave() }

async function openCredentials() { if (busy.value || saveUnknown.value) return; const hadChanges = store.dirty; if (!await store.confirmLeave()) return; if (hadChanges && account.value) { name.value = account.value.name; models.value = [...account.value.offer.allowed_models]; concurrency.value = account.value.concurrency; await nextTick(); store.dirty = false } credentialDialog.value = true }
async function confirmAction(kind: 'submit' | 'pause' | 'resume' | 'revoke') { const hadChanges = store.dirty; if (!await store.confirmLeave()) return; if (hadChanges && account.value) { name.value = account.value.name; models.value = [...account.value.offer.allowed_models]; concurrency.value = account.value.concurrency; await nextTick(); store.dirty = false } action.value = kind }
async function perform() { if (!account.value || !action.value || busy.value) return; busy.value = true; try { await accountAction(account.value.id, action.value, account.value.offer.version); action.value = null; await load() } catch (e) { action.value = null; if ((e as { status?: number }).status === 409) conflict.value = true; else error.value = true } finally { busy.value = false } }
async function performProbe() { if (!account.value || busy.value) return; busy.value = true; probeResult.value = ''; try { await accountAction(account.value.id, 'probe', account.value.offer.version); probeResult.value = t('marketplace.probeComplete') } catch { probeResult.value = t('marketplace.probeFailed') } finally { busy.value = false } }
watch(() => route.params.id, () => { void load() })
onMounted(load); onUnmounted(() => { window.removeEventListener('beforeunload', beforeUnload); store.dirty = false })
</script>
